/* wk_cal.h - the stock constants the READ-ONLY torque-converter lock-up (WK) shadow
 * (app/wk_shadow.c) reads from BELOW 0x80000, where our application overwrites the stock
 * image (generated by tools/gen_wk_cal.py; the host test wk_cal_bytes re-derives every table
 * from the stock image). Data at 0x80000 and above is read IN PLACE through app/cal_inplace.h.
 * (2026-11-20, ~/tcu_sweep/wk_shadow_port.md) */
#ifndef TCU_APP_WK_CAL_H
#define TCU_APP_WK_CAL_H

#if defined(TCU_OUTPUT_PATH)
#error "the lock-up shadow is read-only: an output path may not include wk_cal.h"
#endif

#include <stdint.h>

extern const uint16_t WK_E13C[25];   /* the WK current curve (flash 0xE13C): n, x[12] mbar, y[12] 0.1 mA */
extern const int16_t  WK_E214[79];   /* the NC temperature map (flash 0xE214): nx, ny, x[12], y[5], z[5][12] */

#endif
